// Service worker for the GitHub Pages build: stores the whole app on first visit
// so it opens and works with no network. Generated by scripts/build-pages.mjs.
const BASE = __BASE__;
const VERSION = __VERSION__;
const FILES = __FILES__;
const CACHE = `kurukshetra-gym-${VERSION}`;
const KNOWN = new Set(FILES);

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(FILES.map((file) => new Request(`${BASE}/${file}`, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key.startsWith('kurukshetra-gym-') && key !== CACHE).map((key) => caches.delete(key)))
      )
      .then(() => self.clients.claim())
  );
});

// Member pages (/member/1234) share one pre-rendered shell (/member/_).
const DYNAMIC_ROUTES = [/^(member)\/[^/]+(\/.*)?$/, /^(admin\/users\/edit)\/[^/]+(\/.*)?$/];

function cachedFileFor(pathname) {
  let file = decodeURIComponent(pathname.slice(BASE.length + 1));
  if (file === '' || file.endsWith('/')) file += 'index.html';
  const candidates = [file];
  if (!/\.[a-z0-9]+$/i.test(file)) candidates.push(`${file}/index.html`);
  for (const candidate of [...candidates]) {
    for (const route of DYNAMIC_ROUTES) {
      const match = candidate.match(route);
      if (match) candidates.push(`${match[1]}/_${match[2] ?? '/index.html'}`);
    }
  }
  return candidates.find((candidate) => KNOWN.has(candidate));
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.hostname === 'placehold.co') {
    // The app's placeholder avatars come from placehold.co; draw them locally so they work offline.
    event.respondWith(placeholderImage(url));
    return;
  }
  if (url.origin !== self.location.origin || !url.pathname.startsWith(`${BASE}/`)) return;
  const file = cachedFileFor(url.pathname);
  if (!file) return;
  event.respondWith(
    caches
      .open(CACHE)
      .then((cache) => cache.match(`${BASE}/${file}`))
      .then((cached) => cached ?? fetch(request))
  );
});

function placeholderImage(url) {
  const size = url.pathname.match(/(\d+)x(\d+)/);
  const width = size ? Number(size[1]) : 100;
  const height = size ? Number(size[2]) : 100;
  const label = (url.searchParams.get('text') ?? '').replace(/[<>&"']/g, '').slice(0, 3);
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">` +
    `<rect width="100%" height="100%" fill="#cccccc"/>` +
    `<text x="50%" y="50%" fill="#969696" font-family="sans-serif" font-size="${Math.round(Math.min(width, height) * 0.4)}" ` +
    `text-anchor="middle" dominant-baseline="central">${label}</text></svg>`;
  return new Response(svg, { headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'no-store' } });
}
